// 문자열은 snprintf 로 길이를 반드시 제한 (오버플로 방지)
snprintf(logLine, sizeof(logLine), "T=%d V=%d", temp, volt);

// 피할 것: malloc/new, String(동적), std::vector 남발
// 컴파일 출력의 RAM 사용량을 늘 확인

// 나쁨: 큰 지역 배열 → 스택 넘침
void process() { char buf[2048]; ... }   // 스택에 2KB!

// 좋음: 정적으로 (스택 밖)
void process() { static char buf[2048]; ... }

// 재귀 대신 반복문, ISR 은 얕게
