// 고정소수점: 3.14 를 314 로 (×100)
int32_t temp_x100 = 2537;         // = 25.37도
int32_t avg = (a_x100 + b_x100) / 2;
// 나눗셈 → 시프트: x / 2 == x >> 1,  x * 8 == x << 3

// 와치독: 8초 안에 wdt_reset() 못 오면 자동 리셋
wdt_enable(WDTO_8S);
void loop() { doWork(); wdt_reset(); }
